-- Empty schema: no source catalogue, accounts, transactions or credentials.
CREATE TABLE admin_users(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'ADMIN' CHECK(role IN ('SUPER_ADMIN','ADMIN','CATALOG_MANAGER','ORDER_MANAGER')),status TEXT NOT NULL DEFAULT 'ACTIVE',token_version INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE customers(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,phone TEXT NOT NULL DEFAULT '',password_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',token_version INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE customer_addresses(id SERIAL PRIMARY KEY,customer_id INT NOT NULL REFERENCES customers(id),label TEXT NOT NULL DEFAULT '',country TEXT NOT NULL DEFAULT '',region TEXT NOT NULL DEFAULT '',governorate TEXT NOT NULL DEFAULT '',area TEXT NOT NULL DEFAULT '',block TEXT NOT NULL DEFAULT '',street TEXT NOT NULL DEFAULT '',building TEXT NOT NULL DEFAULT '',floor TEXT NOT NULL DEFAULT '',apartment TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',postal_code TEXT NOT NULL DEFAULT '',is_default BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE store_settings(key TEXT PRIMARY KEY,value JSONB NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE categories(id SERIAL PRIMARY KEY,name_en TEXT NOT NULL DEFAULT '',name_ar TEXT NOT NULL DEFAULT '',slug TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')),priority INT NOT NULL DEFAULT 0,image_url TEXT,image_alt_en TEXT,image_alt_ar TEXT,badge_en TEXT,badge_ar TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE brands(id SERIAL PRIMARY KEY,name TEXT NOT NULL,name_en TEXT NOT NULL DEFAULT '',name_ar TEXT NOT NULL DEFAULT '',slug TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')),priority INT NOT NULL DEFAULT 0,image_url TEXT,image_alt_en TEXT,image_alt_ar TEXT,search_aliases TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE products(id SERIAL PRIMARY KEY,source_url TEXT UNIQUE NOT NULL,source_identity_hash TEXT UNIQUE NOT NULL,sku TEXT NOT NULL DEFAULT '',barcode TEXT NOT NULL DEFAULT '',slug TEXT UNIQUE NOT NULL,name_en TEXT NOT NULL DEFAULT '',name_ar TEXT NOT NULL DEFAULT '',short_description_en TEXT NOT NULL DEFAULT '',short_description_ar TEXT NOT NULL DEFAULT '',details_en TEXT NOT NULL DEFAULT '',details_ar TEXT NOT NULL DEFAULT '',how_to_use_en TEXT NOT NULL DEFAULT '',how_to_use_ar TEXT NOT NULL DEFAULT '',brand_id INT REFERENCES brands(id),category_id INT NOT NULL REFERENCES categories(id),source_price NUMERIC(18,3),selling_price NUMERIC(18,3) NOT NULL CHECK(selling_price>=0),regular_price NUMERIC(18,3),currency TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'INACTIVE' CHECK(status IN ('ACTIVE','INACTIVE','ARCHIVED')),stock_status TEXT NOT NULL DEFAULT 'IN_STOCK' CHECK(stock_status IN ('IN_STOCK','OUT_OF_STOCK')),inventory_quantity INT CHECK(inventory_quantity>=0),low_stock_threshold INT NOT NULL DEFAULT 5,priority INT NOT NULL DEFAULT 0,routine_step TEXT,translation_status TEXT DEFAULT 'REVIEWED',variants_enabled BOOLEAN NOT NULL DEFAULT false,custom_fields JSONB NOT NULL DEFAULT '{}',seo_title_en TEXT,seo_title_ar TEXT,seo_description_en TEXT,seo_description_ar TEXT,deleted_at TIMESTAMPTZ,archived_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX products_category ON products(category_id,status); CREATE INDEX products_brand ON products(brand_id); CREATE INDEX products_public ON products(priority DESC,id DESC) WHERE status='ACTIVE' AND deleted_at IS NULL;
CREATE TABLE product_images(id SERIAL PRIMARY KEY,product_id INT NOT NULL REFERENCES products(id),cloudinary_url TEXT NOT NULL,cloudinary_public_id TEXT,image_order INT NOT NULL DEFAULT 1,width INT,height INT,alt_en TEXT,alt_ar TEXT,source_filename TEXT,UNIQUE(product_id,image_order));
CREATE TABLE product_category_memberships(product_id INT REFERENCES products(id),category_id INT REFERENCES categories(id),PRIMARY KEY(product_id,category_id)); CREATE INDEX membership_category ON product_category_memberships(category_id,product_id);
CREATE TABLE product_variants(id SERIAL PRIMARY KEY,product_id INT NOT NULL REFERENCES products(id),name_en TEXT NOT NULL,name_ar TEXT NOT NULL DEFAULT '',sku TEXT DEFAULT '',color_hex TEXT,image_url TEXT,inventory_quantity INT CHECK(inventory_quantity>=0),stock_status TEXT NOT NULL DEFAULT 'IN_STOCK',status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','ACTIVE','ARCHIVED')),priority INT DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE offers(id SERIAL PRIMARY KEY,title_en TEXT NOT NULL,title_ar TEXT NOT NULL DEFAULT '',discount_percent NUMERIC(6,3) NOT NULL CHECK(discount_percent>0 AND discount_percent<=100),product_id INT REFERENCES products(id),category_id INT REFERENCES categories(id),active BOOLEAN DEFAULT true,priority INT DEFAULT 0,starts_at TIMESTAMPTZ DEFAULT NOW(),ends_at TIMESTAMPTZ,CHECK((product_id IS NOT NULL)::int+(category_id IS NOT NULL)::int=1));
CREATE TABLE discounts(id SERIAL PRIMARY KEY,title TEXT NOT NULL,title_ar TEXT DEFAULT '',type TEXT NOT NULL CHECK(type IN ('PRODUCT','ORDER','BXGY','SHIPPING')),method TEXT NOT NULL CHECK(method IN ('CODE','AUTOMATIC')),code TEXT UNIQUE,value_type TEXT NOT NULL CHECK(value_type IN ('PERCENT','FIXED')),value NUMERIC(18,3) NOT NULL,target TEXT DEFAULT 'ALL',target_ids INT[] NOT NULL DEFAULT '{}',get_target TEXT DEFAULT 'ALL',get_ids INT[] NOT NULL DEFAULT '{}',minimum_amount NUMERIC(18,3) NOT NULL DEFAULT 0,buy_quantity INT DEFAULT 1,get_quantity INT DEFAULT 1,usage_limit INT,once_per_customer BOOLEAN DEFAULT false,combines BOOLEAN DEFAULT false,active BOOLEAN DEFAULT true,starts_at TIMESTAMPTZ DEFAULT NOW(),ends_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE order_reference_counter(id INT PRIMARY KEY CHECK(id=1),value BIGINT NOT NULL DEFAULT 0); INSERT INTO order_reference_counter(id,value) VALUES(1,0);
CREATE TABLE orders(id SERIAL PRIMARY KEY,order_number TEXT UNIQUE NOT NULL,customer_id INT REFERENCES customers(id),customer_name TEXT NOT NULL,customer_phone TEXT NOT NULL,customer_email TEXT,customer_address TEXT NOT NULL,currency TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('PENDING_PAYMENT','CONFIRMED','PROCESSING','READY_FOR_DELIVERY','OUT_FOR_DELIVERY','DELIVERED','CANCELLED','RETURNED')),payment_method TEXT NOT NULL,total_amount NUMERIC(18,3) NOT NULL,subtotal NUMERIC(18,3) NOT NULL,delivery_fee NUMERIC(18,3) NOT NULL,discount_amount NUMERIC(18,3) NOT NULL DEFAULT 0,tax_amount NUMERIC(18,3) NOT NULL DEFAULT 0,discount_details JSONB DEFAULT '[]',tax_details JSONB DEFAULT '{}',idempotency_key TEXT UNIQUE NOT NULL,checkout_fingerprint TEXT NOT NULL,tracking_token_hash TEXT NOT NULL,inventory_reserved BOOLEAN NOT NULL DEFAULT false,delivery_estimated_from TIMESTAMPTZ,delivery_estimated_to TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX orders_customer ON orders(customer_id,id DESC); CREATE INDEX orders_status_date ON orders(status,created_at);
CREATE TABLE order_items(id SERIAL PRIMARY KEY,order_id INT NOT NULL REFERENCES orders(id),product_id INT NOT NULL REFERENCES products(id),variant_id INT REFERENCES product_variants(id),variant_name_en TEXT,variant_name_ar TEXT,product_name_en TEXT NOT NULL DEFAULT '',product_name_ar TEXT NOT NULL DEFAULT '',quantity INT NOT NULL CHECK(quantity>0),price_at_purchase NUMERIC(18,3) NOT NULL CHECK(price_at_purchase>=0),inventory_reserved_quantity INT NOT NULL DEFAULT 0);
CREATE TABLE discount_redemptions(id SERIAL PRIMARY KEY,discount_id INT NOT NULL REFERENCES discounts(id),order_id INT NOT NULL REFERENCES orders(id),customer_key TEXT NOT NULL,amount NUMERIC(18,3) NOT NULL,released BOOLEAN DEFAULT false,UNIQUE(discount_id,order_id));
CREATE TABLE payments(id SERIAL PRIMARY KEY,order_id INT NOT NULL REFERENCES orders(id),provider TEXT NOT NULL,provider_invoice_id TEXT,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SUCCESS','FAILED')),amount NUMERIC(18,3) NOT NULL,currency TEXT NOT NULL,raw_reference TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(provider,provider_invoice_id));
CREATE TABLE refunds(id SERIAL PRIMARY KEY,payment_id INT NOT NULL REFERENCES payments(id),order_id INT NOT NULL REFERENCES orders(id),amount NUMERIC(18,3) NOT NULL CHECK(amount>0),currency TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SUCCESS','FAILED','UNKNOWN')),reason TEXT NOT NULL,admin_id INT REFERENCES admin_users(id),idempotency_key TEXT UNIQUE NOT NULL,provider_refund_id TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE order_status_history(id SERIAL PRIMARY KEY,order_id INT REFERENCES orders(id),old_status TEXT,new_status TEXT NOT NULL,reason TEXT,changed_by_admin_id INT REFERENCES admin_users(id),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE return_requests(id SERIAL PRIMARY KEY,order_id INT NOT NULL REFERENCES orders(id),reason TEXT NOT NULL,reason_code TEXT NOT NULL,items JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'REQUESTED' CHECK(status IN ('REQUESTED','APPROVED','REJECTED','RECEIVED','CLOSED')),admin_note TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE return_history(id SERIAL PRIMARY KEY,return_id INT REFERENCES return_requests(id),status TEXT NOT NULL,note TEXT,admin_id INT REFERENCES admin_users(id),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE return_evidence(id UUID PRIMARY KEY,return_id INT NOT NULL REFERENCES return_requests(id),image BYTEA NOT NULL);
CREATE TABLE cash_transactions(id SERIAL PRIMARY KEY,order_id INT NOT NULL REFERENCES orders(id),kind TEXT NOT NULL CHECK(kind IN ('COLLECTION','REFUND')),amount NUMERIC(18,3) NOT NULL CHECK(amount>0),note TEXT NOT NULL,admin_id INT REFERENCES admin_users(id),idempotency_key TEXT UNIQUE NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE UNIQUE INDEX one_cash_collection ON cash_transactions(order_id) WHERE kind='COLLECTION';
CREATE TABLE admin_audit_log(id SERIAL PRIMARY KEY,admin_id INT REFERENCES admin_users(id),action TEXT NOT NULL,entity_id TEXT,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE admin_saved_views(id SERIAL PRIMARY KEY,admin_id INT REFERENCES admin_users(id),name TEXT NOT NULL,filters JSONB NOT NULL,UNIQUE(admin_id,name));
CREATE TABLE media_assets(id UUID PRIMARY KEY,url TEXT UNIQUE NOT NULL,provider TEXT NOT NULL,public_id TEXT NOT NULL,width INT NOT NULL,height INT NOT NULL,bytes INT NOT NULL,purpose TEXT NOT NULL,admin_id INT REFERENCES admin_users(id),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE mock_provider_payments(invoice_id UUID PRIMARY KEY,order_reference TEXT NOT NULL,amount NUMERIC(18,3) NOT NULL,currency TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING');
CREATE TABLE mock_provider_refunds(id UUID PRIMARY KEY,invoice_id UUID NOT NULL REFERENCES mock_provider_payments(invoice_id),amount NUMERIC(18,3) NOT NULL,idempotency_key TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'SUCCESS');
